def tau_n_12(n, factors):
    if n == 1:
        # n=1 has factors {}. tau(1^12) = tau(1) = 1.
        return 1

    # n = p1^e1 * p2^e2 * ...
    # n^12 = p1^(12*e1) * p2^(12*e2) * ...
    # tau(n^12) = (12*e1 + 1) * (12*e2 + 1) * ...

    tau_val = 1
    for exponent in factors.values():
        tau_val *= (12 * exponent + 1)
    return tau_val

