def tau_n_12(n):
    """
    Calculates tau(n^12), where tau is the number of divisors function.
    This relies on prime factorization of n.
    """
    if n == 1:
        return 1

    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1

    # If n = p1^a1 * p2^a2 * ..., then n^12 = p1^(12a1) * p2^(12a2) * ...
    # tau(n^12) = (12a1 + 1) * (12a2 + 1) * ...

    result = 1
    for prime, exponent in factors.items():
        result *= (12 * exponent + 1)
    return result

